parameters.jsCode:
const files = [];
for (const item of $input.all()) {
  if (item.json.name && item.json.id) files.push({ name: item.json.name, id: item.json.id });
}
const excelFiles = files.filter(f => f.name.endsWith('.xlsx') || f.name.endsWith('.xls') || f.name.endsWith('.csv'));
const fileList = excelFiles.map((f, i) => `${i+1}. 📄 ${f.name}`).join('\n');
const sessionId = $('select_file,transform,question,visu,sharing,loading,consult,conversation ?').first().json.sessionId;
return [{ json: { text: `📂 Fichiers disponibles :\n\n${fileList}\n\nTapez le nom exact du fichier à traiter.`, files: excelFiles, type: 'select_file', sessionId } }];

const chatInput = items[0].json.chatInput || '';
const hasFileName = /\.(xlsx|xls|csv)\b/i.test(chatInput) ? 'yes' : 'no';
return [{ json: { ...items[0].json, hasFileName } }];

const spreadsheetId = items[0].json.id;
if (!spreadsheetId) throw new Error('Copie/Conversion échouée');
return [{ json: { spreadsheetId } }];

const sheets = items[0].json.sheets || [];
if (sheets.length === 0) throw new Error('Aucune feuille trouvée');
const spreadsheetId = $('extraire spreadsheet id').first().json.spreadsheetId;
return sheets.map(s => ({
  json: { spreadsheetId, sheetName: s.properties.title, sheetId: s.properties.sheetId, totalRows: s.properties.gridProperties.rowCount || 1000 }
}));

const sheets = $input.all();
const spreadsheetId = sheets[0]?.json.spreadsheetId;
const fileName = $('extraire nom de fichier').first().json.fileName;
const sessionId = $('session id').first().json.sessionId;
const sheetsList = sheets.map(s => `- ${s.json.sheetName} (jusqu'à ${s.json.totalRows} lignes)`).join('\n');
return [{ json: {
  sessionId, fileName, spreadsheetId,
  driveWorkingFileId: spreadsheetId,
  driveSourceFileId: $('extraire seulemnt le fichier excel choisi').first().json.id,
  sheetUrl: `https://docs.google.com/spreadsheets/d/${spreadsheetId}`,
  text: `📁 Fichier sélectionné : ${fileName}\n\n🗂️ Feuilles détectées :\n${sheetsList}\n\n🔗 Copie de travail : https://docs.google.com/spreadsheets/d/${spreadsheetId}\n\nQue voulez-vous faire ? (nettoyer, dates, doublons, colonne calculée, format, TCD...)`,
  type: 'select_file'
}}];

const row = items[0]?.json;
const sessionId = $('session id').first().json.sessionId;
const chatInput = $('session id').first().json.chatInput;
if (!row || !row.spreadsheet_id) {
  return [{ json: { sessionStatus: 'missing', sessionId, chatInput, text: "⚠️ Aucun fichier sélectionné. Dites-moi d'abord quel fichier vous voulez traiter (ex: 'ouvre bi_dimensions.xlsx')." } }];
}
return [{ json: { sessionStatus: 'ready', spreadsheetId: row.spreadsheet_id, fileName: row.file_name, sessionId, chatInput } }];

const raw = items[0].json.output || '{}';
let action;
try { action = JSON.parse(raw.replace(/```json\s*/g,'').replace(/```/g,'').trim()); } catch(e) { action = { action: 'clean_text', columns: [], case: 'upper' }; }
const ctx = $('🔎 Vérifier session (Transform)').first().json;
return [{ json: { ...action, spreadsheetId: ctx.spreadsheetId, fileName: ctx.fileName, sessionId: ctx.sessionId } }];

const meta = items[0].json;
const action = $('🧩 Parser action transformation').first().json;
const sheets = meta.sheets || [];
const match = sheets.find(s => s.properties.title === action.sheetName) || sheets[0];
return [{ json: { ...action, sheetName: match.properties.title, sheetGid: match.properties.sheetId } }];

const action = $('🔀 Type de transformation').first().json;
const values = items[0].json.values || [];
const headers = values[0] || [];
const caseFn = { upper: s=>String(s).toUpperCase(), lower: s=>String(s).toLowerCase(), proper: s=>String(s).replace(/\w\S*/g, t=>t[0].toUpperCase()+t.slice(1).toLowerCase()) }[action.case] || (s=>String(s).trim());
const cols = (action.columns||[]).map(c => String(c).trim().toLowerCase());
const targetIdx = headers.map((h,i)=>[String(h).trim().toLowerCase(),i]).filter(([h])=>cols.includes(h)).map(([,i])=>i);
const cleaned = values.map((row, r) => r===0 ? row : row.map((cell,i) => targetIdx.includes(i) ? caseFn(String(cell ?? '').trim()) : cell));
return [{ json: { spreadsheetId: action.spreadsheetId, sheetName: action.sheetName, range: `${action.sheetName}!A1`, values: cleaned, columns: action.columns, sessionId: action.sessionId } }];

const action = $('🔀 Type de transformation').first().json;
const values = items[0].json.values || [];
const headers = values[0] || [];
const target = String((action.columns||[])[0]||'').trim().toLowerCase();
const colIdx = headers.findIndex(h => String(h).trim().toLowerCase() === target);
function parseAny(v){
  if(!v) return v;
  const s = String(v).trim(); let m;
  if((m = s.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{4})$/))) return `${m[3]}-${String(m[2]).padStart(2,'0')}-${String(m[1]).padStart(2,'0')}`;
  if((m = s.match(/^(\d{4})[\/\-.](\d{1,2})[\/\-.](\d{1,2})$/))) return `${m[1]}-${String(m[2]).padStart(2,'0')}-${String(m[3]).padStart(2,'0')}`;
  const d = new Date(s); if(!isNaN(d)) return d.toISOString().slice(0,10);
  return s;
}
const out = values.map((row,r)=> r===0||colIdx<0 ? row : row.map((c,i)=> i===colIdx ? parseAny(c) : c));
return [{ json: { spreadsheetId: action.spreadsheetId, sheetName: action.sheetName, sheetGid: action.sheetGid, range: `${action.sheetName}!A1`, values: out, colIdx, sessionId: action.sessionId } }];

const ctx = $('📅 Normaliser dates').first().json;
const body = { requests: [{ repeatCell: { range: { sheetId: ctx.sheetGid, startRowIndex: 1, startColumnIndex: ctx.colIdx, endColumnIndex: ctx.colIdx + 1 }, cell: { userEnteredFormat: { numberFormat: { type: 'DATE', pattern: 'yyyy-mm-dd' } } }, fields: 'userEnteredFormat.numberFormat' } }] };
return [{ json: { spreadsheetId: ctx.spreadsheetId, body, sessionId: ctx.sessionId } }];

const action = $('🔀 Type de transformation').first().json;
const values = items[0].json.values || [];
const headers = values[0] || [];
const rows = values.slice(1);
const seen = new Set(); const kept = [];
for (const row of rows) { const key = JSON.stringify(row); if (!seen.has(key)) { seen.add(key); kept.push(row); } }
const removed = rows.length - kept.length;
const padded = kept.concat(Array.from({ length: removed }, () => headers.map(() => '')));
const out = [headers, ...padded];
return [{ json: { spreadsheetId: action.spreadsheetId, sheetName: action.sheetName, range: `${action.sheetName}!A1`, values: out, removed, sessionId: action.sessionId } }];

const action = $('🔀 Type de transformation').first().json;
const values = items[0].json.values || [];
const headers = values[0] || [];
const rows = values.length;
const nextColIdx = headers.length;
const colLetter = String.fromCharCode(65 + nextColIdx);
const newHeader = action.targetColumn || 'Calcul';
const formulas = [[newHeader]];
for (let r = 2; r <= rows; r++) { formulas.push([ String(action.formula||'').replace(/\{row\}/g, r) ]); }
return [{ json: { spreadsheetId: action.spreadsheetId, sheetName: action.sheetName, range: `${action.sheetName}!${colLetter}1`, values: formulas, colLetter, newHeader, sessionId: action.sessionId } }];

const action = $('🔀 Type de transformation').first().json;
const headers = (items[0].json.values || [[]])[0] || [];
const patterns = { DATE: {type:'DATE', pattern:'yyyy-mm-dd'}, CURRENCY: {type:'CURRENCY', pattern:'#,##0.00 €'}, PERCENT: {type:'PERCENT', pattern:'0.00%'}, NUMBER: {type:'NUMBER', pattern:'#,##0.00'}, TEXT: {type:'TEXT'} };
const fmt = patterns[action.numberFormat] || patterns.NUMBER;
const cols = (action.columns||[]).map(c => String(c).trim().toLowerCase());
const idxs = headers.map((h,i)=>[String(h).trim().toLowerCase(), i]).filter(([h])=>cols.includes(h)).map(([,i])=>i);
const requests = idxs.map(i => ({ repeatCell: { range: { sheetId: action.sheetGid, startRowIndex: 1, startColumnIndex: i, endColumnIndex: i + 1 }, cell: { userEnteredFormat: { numberFormat: fmt } }, fields: 'userEnteredFormat.numberFormat' } }));
return [{ json: { spreadsheetId: action.spreadsheetId, body: { requests }, columns: action.columns, numberFormat: action.numberFormat, sessionId: action.sessionId } }];

const action = $('🔀 Type de transformation').first().json;
const values = items[0].json.values || [];
const headers = values[0] || [];
const rowCount = values.length; const colCount = headers.length;
const idx = name => headers.findIndex(h => String(h).trim().toLowerCase() === String(name).trim().toLowerCase());
const pivotRows = (action.pivotRows||[]).map(c => ({ sourceColumnOffset: idx(c), showTotals: true, sortOrder: 'ASCENDING' })).filter(r=>r.sourceColumnOffset>=0);
const pivotValues = (action.pivotValues||[]).map(c => ({ sourceColumnOffset: idx(c), summarizeFunction: action.pivotAggregation || 'SUM' })).filter(v=>v.sourceColumnOffset>=0);
const newSheetId = Math.floor(Date.now()/1000) % 2000000000;
const newSheetTitle = `TCD_${newSheetId}`;
const body = { requests: [
  { addSheet: { properties: { sheetId: newSheetId, title: newSheetTitle } } },
  { updateCells: { rows: [{ values: [{ pivotTable: { source: { sheetId: action.sheetGid, startRowIndex: 0, startColumnIndex: 0, endRowIndex: rowCount, endColumnIndex: colCount }, rows: pivotRows, values: pivotValues } }] }], start: { sheetId: newSheetId, rowIndex: 0, columnIndex: 0 }, fields: 'pivotTable' } }
] };
return [{ json: { spreadsheetId: action.spreadsheetId, body, newSheetTitle, sessionId: action.sessionId } }];

const row = items[0]?.json;
const sessionId = $('session id').first().json.sessionId;
if (!row || !row.spreadsheet_id) {
  return [{ json: { text: "⚠️ Aucun fichier en cours. Choisissez d'abord un fichier à traiter.", sessionId, type: 'consult' } }];
}
return [{ json: { text: `🔎 Fichier en cours : ${row.file_name}\n🔗 Copie de travail (vérifiez en direct) :\nhttps://docs.google.com/spreadsheets/d/${row.spreadsheet_id}`, sessionId, type: 'consult' } }];

const row = items[0]?.json;
const sessionId = $('session id').first().json.sessionId;
const chatInput = $('session id').first().json.chatInput;
if (!row || !row.spreadsheet_id) {
  return [{ json: { sessionStatus: 'missing', sessionId, text: "⚠️ Aucun fichier sélectionné pour l'instant." } }];
}
return [{ json: { sessionStatus: 'ready', spreadsheetId: row.spreadsheet_id, fileName: row.file_name, sessionId, chatInput } }];

const data = items[0].json;
const values = data.values || [];
const headers = values[0] || [];
const rows = values.slice(1);
const stats = {};
headers.forEach((h, i) => {
  const colVals = rows.map(r => r[i]).filter(v => v !== undefined && v !== '');
  const numeric = colVals.filter(v => v !== '' && !isNaN(parseFloat(v)) && isFinite(v)).map(Number);
  const distinct = new Set(colVals.map(String));
  if (numeric.length > colVals.length * 0.6 && numeric.length > 0) {
    stats[h] = { non_empty: colVals.length, distinct: distinct.size, sum: +numeric.reduce((a,b)=>a+b,0).toFixed(2), avg: +(numeric.reduce((a,b)=>a+b,0)/numeric.length).toFixed(2), min: Math.min(...numeric), max: Math.max(...numeric) };
  } else {
    stats[h] = { non_empty: colVals.length, distinct: distinct.size, top_values: [...distinct].slice(0,5) };
  }
});
const sheetName = (data.range||'').split('!')[0].replace(/'/g,'') || 'Sheet1';
return [{ json: { totalRows: rows.length, totalColumns: headers.length, columnStats: stats, sheetName } }];

