const raw = items[0].json.output || '{}';
let result;
try { result = JSON.parse(raw.replace(/```json|```/g,'').trim()); } catch(e) { result = { channel: 'email', message: 'Résultats ETL Flowrecom', subject: 'Rapport ETL' }; }
return [{ json: { ...result, sessionId: items[0].json.sessionId, type: 'sharing', text: `✅ Partage préparé pour ${result.channel}` } }];

const row = items[0]?.json;
const sessionId = $('session id').first().json.sessionId;
if (!row || !row.spreadsheet_id) {
  return [{ json: { sessionStatus: 'missing', sessionId, text: "⚠️ Aucun fichier à charger pour l'instant." } }];
}
return [{ json: { sessionStatus: 'ready', spreadsheetId: row.spreadsheet_id, fileName: row.file_name, sessionId } }];

const row = $('🔎 Vérifier session (Loading)').first().json;
const date = new Date().toISOString().slice(0,10);
const base = row.fileName.replace(/\.[^.]+$/, '');
const finalName = `FINAL_${base}_${date}.xlsx`;
const binary = items[0].binary;
binary.data.fileName = finalName;
binary.data.mimeType = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
return [{ json: { finalName, sessionId: row.sessionId }, binary }];

const finalName = $('🏷️ Nommer fichier final').first().json.finalName;
const sessionId = $('session id').first().json.sessionId;
return [{ json: {
  text: `✅ Chargement terminé !

📄 Fichier : ${finalName}
💽 Local : C:\Users\Hanen GB\Desktop\n8n ETL\output\${finalName}
☁️ Google Drive (Final) : dossier Flowrecom/Final
📎 SharePoint : voir logs d'exécution (nécessite credential configurée)

Le fichier nettoyé et transformé est prêt.`,
  sessionId, type: 'loading'
}}];

const item = items[0].json;
const response = {
  text: item.text || item.response || 'Traitement terminé.',
  type: item.type || 'general',
  sessionId: item.sessionId,
  charts: item.charts || null,
  key_metrics: item.key_metrics || null,
  summary: item.summary || null,
  timestamp: new Date().toISOString()
};
return [{ json: response }];
